t.script:
odoo.define("frontdesk.kiosk_mode_frontdesk", async function (require) {

    const { FrontdeskAction } = require('@frontdesk/js/frontdesk');
    const { App, Component,onMounted, onPatched, useComponent, useEnv } = require("@odoo/owl");
    const { makeEnv, startServices } = require('@web/env');
    const { templates } = require("@web/core/assets");
    const { registry } = require('@web/core/registry');
    const { hotkeyService } = require("@web/core/hotkeys/hotkey_service");


    const serviceRegistry = registry.category("services");

    const context = {
        station_id: '',
        token: '',
        lang: '',
        isMobile: '',
    };

    const root = document.querySelector('.o-main-components-container');
    if (!registry.category("services").contains("hotkey")) {
        registry.category("services").add("hotkey", hotkeyService);
    }









    console.log(Component.env);
    Component.env.services.hotkey = hotkeyService;
    const app = new App(FrontdeskAction, {

        env: Component.env,
        dev: Component.env.isDebug(),
        templates,

        translatableAttributes: ["data-tooltip"],
        translateFn: Component.env._t,
        props: {
            action: {
                context: context
            }
        }
    });
    app.mount(root, {
        Component: FrontdeskAction,
        props: {
            action: {
                context: context
            }
        }
    });
});
